import { verifyAdmin } from '../lib/auth';
import { forbidden } from 'next/navigation';

export default async function AdminPage() {
  const { isAdmin, session } = await verifyAdmin();

  if (!isAdmin) {
    forbidden();
  }

  return (
    <div style={{ padding: '2rem', maxWidth: '800px', margin: '0 auto' }}>
      <h1 style={{ color: '#333', borderBottom: '2px solid #0070f3', paddingBottom: '0.5rem' }}>
        Admin Dashboard
      </h1>
      <p style={{ color: '#666', marginTop: '1rem' }}>
        Welcome, <strong>{session?.name}</strong>! You have admin privileges.
      </p>
      <div style={{ marginTop: '2rem', padding: '1.5rem', backgroundColor: '#f5f5f5', borderRadius: '8px' }}>
        <h2 style={{ color: '#333', marginBottom: '1rem' }}>Admin Controls</h2>
        <ul style={{ color: '#666', lineHeight: '1.8' }}>
          <li>User Management</li>
          <li>System Settings</li>
          <li>Analytics Dashboard</li>
          <li>Security Logs</li>
        </ul>
      </div>
    </div>
  );
}

export default function ForbiddenPage() {
  return (
    <div style={{ 
      minHeight: '100vh', 
      display: 'flex', 
      flexDirection: 'column',
      alignItems: 'center', 
      justifyContent: 'center',
      backgroundColor: '#f8f9fa',
      fontFamily: 'system-ui, -apple-system, sans-serif'
    }}>
      <div style={{
        textAlign: 'center',
        padding: '2rem'
      }}>
        <h1 style={{ 
          fontSize: '6rem', 
          margin: '0',
          color: '#dc3545',
          fontWeight: 'bold'
        }}>
          403
        </h1>
        <h2 style={{ 
          fontSize: '1.5rem', 
          color: '#333',
          margin: '1rem 0'
        }}>
          Access Forbidden
        </h2>
        <p style={{ 
          color: '#666',
          maxWidth: '400px',
          margin: '1rem auto 2rem',
          lineHeight: '1.6'
        }}>
          You don't have permission to access this page. 
          This area is restricted to administrators only.
        </p>
        <a 
          href="/"
          style={{
            display: 'inline-block',
            padding: '0.75rem 1.5rem',
            backgroundColor: '#0070f3',
            color: 'white',
            textDecoration: 'none',
            borderRadius: '5px',
            fontWeight: '500',
            transition: 'background-color 0.2s'
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = '#0051a8';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = '#0070f3';
          }}
        >
          Go Back Home
        </a>
      </div>
    </div>
  );
}
